// Símbolo ORVEXA "Impacto": la cabeza del pilote vista desde arriba con las ondas del golpe
// que se deshacen en cuadritos. Generado desde el diseño del logo (viewBox 0 0 200 200).
// No editar a mano.

class LogoRect {
  final double x, y, w, h, rx, opacity, stroke;
  final bool core; // la cabeza del pilote (blanco); el resto va en amarillo
  const LogoRect(this.x, this.y, this.w, this.h, {this.rx = 0, this.opacity = 1, this.stroke = 0, this.core = false});
}

